import React from 'react';
import { cosineSimilarity } from '../algorithms/contrastiveLearning';
import './SensorComparison.css';

function SensorComparison({ embeddings, activeSensors, alignmentScore }) {
  const sensors = Object.keys(embeddings);

  const computePairwiseSimilarity = () => {
    const similarities = [];

    for (let i = 0; i < sensors.length; i++) {
      for (let j = i + 1; j < sensors.length; j++) {
        const sim = cosineSimilarity(
          embeddings[sensors[i]],
          embeddings[sensors[j]]
        );
        similarities.push({
          sensorA: sensors[i],
          sensorB: sensors[j],
          similarity: sim
        });
      }
    }

    return similarities;
  };

  const similarities = sensors.length >= 2 ? computePairwiseSimilarity() : [];

  const getSensorColor = (sensor) => {
    const colors = {
      'DIGIT': '#00d4ff',
      'GelSight': '#7b2ff7',
      'ReSkin': '#ff6b00'
    };
    return colors[sensor] || '#ffffff';
  };

  const getEmbeddingStats = (embedding) => {
    if (!embedding || embedding.length === 0) {
      return { mean: 0, std: 0, min: 0, max: 0 };
    }

    const mean = embedding.reduce((a, b) => a + b, 0) / embedding.length;
    const variance = embedding.reduce((a, b) => a + (b - mean) ** 2, 0) / embedding.length;
    const std = Math.sqrt(variance);
    const min = Math.min(...embedding);
    const max = Math.max(...embedding);

    return { mean, std, min, max };
  };

  return (
    <div className="sensor-comparison">
      <div className="comparison-header">
        <h2>Cross-Sensor Embedding Analysis</h2>
        <div className="overall-alignment">
          <span>Overall Alignment Score:</span>
          <span className="alignment-value" style={{ color: getSensorColor('DIGIT') }}>
            {alignmentScore.toFixed(4)}
          </span>
        </div>
      </div>

      <div className="comparison-grid">
        {/* Pairwise Similarities */}
        <div className="comparison-section glass-dark">
          <h3>Pairwise Similarities</h3>
          {similarities.length > 0 ? (
            <div className="similarity-list">
              {similarities.map((sim, idx) => (
                <div key={idx} className="similarity-item">
                  <div className="similarity-sensors">
                    <span style={{ color: getSensorColor(sim.sensorA) }}>
                      {sim.sensorA}
                    </span>
                    <span className="similarity-arrow">↔</span>
                    <span style={{ color: getSensorColor(sim.sensorB) }}>
                      {sim.sensorB}
                    </span>
                  </div>
                  <div className="similarity-bar">
                    <div
                      className="similarity-fill"
                      style={{
                        width: `${Math.max(0, Math.min(100, (sim.similarity + 1) * 50))}%`,
                        background: `linear-gradient(90deg, ${getSensorColor(sim.sensorA)}, ${getSensorColor(sim.sensorB)})`
                      }}
                    />
                  </div>
                  <span className="similarity-value mono">
                    {sim.similarity.toFixed(4)}
                  </span>
                </div>
              ))}
            </div>
          ) : (
            <div className="no-data">Activate at least 2 sensors to compare</div>
          )}
        </div>

        {/* Embedding Statistics */}
        <div className="comparison-section glass-dark">
          <h3>Embedding Statistics</h3>
          <div className="stats-grid">
            {sensors.map(sensor => {
              const stats = getEmbeddingStats(embeddings[sensor]);
              return (
                <div key={sensor} className="sensor-stats">
                  <h4 style={{ color: getSensorColor(sensor) }}>{sensor}</h4>
                  <div className="stats-list">
                    <div className="stat-item">
                      <span className="stat-label">Mean:</span>
                      <span className="stat-value mono">{stats.mean.toFixed(4)}</span>
                    </div>
                    <div className="stat-item">
                      <span className="stat-label">Std Dev:</span>
                      <span className="stat-value mono">{stats.std.toFixed(4)}</span>
                    </div>
                    <div className="stat-item">
                      <span className="stat-label">Min:</span>
                      <span className="stat-value mono">{stats.min.toFixed(4)}</span>
                    </div>
                    <div className="stat-item">
                      <span className="stat-label">Max:</span>
                      <span className="stat-value mono">{stats.max.toFixed(4)}</span>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Sensor Descriptions */}
        <div className="comparison-section glass-dark full-width">
          <h3>Sensor Technologies</h3>
          <div className="sensor-descriptions">
            <div className="sensor-desc">
              <h4 style={{ color: getSensorColor('DIGIT') }}>DIGIT</h4>
              <p>
                <strong>Type:</strong> Gel-based optical tactile sensor<br />
                <strong>Method:</strong> Captures gel deformation as high-resolution images<br />
                <strong>Dimensionality:</strong> 1024 features (32×32 image)<br />
                <strong>Strengths:</strong> High spatial resolution, rich texture information
              </p>
            </div>
            <div className="sensor-desc">
              <h4 style={{ color: getSensorColor('GelSight') }}>GelSight</h4>
              <p>
                <strong>Type:</strong> Marker tracking optical sensor<br />
                <strong>Method:</strong> Tracks displacement of embedded markers in gel<br />
                <strong>Dimensionality:</strong> 512 features (16×16 markers × 2D)<br />
                <strong>Strengths:</strong> Accurate force/shear measurement, robust tracking
              </p>
            </div>
            <div className="sensor-desc">
              <h4 style={{ color: getSensorColor('ReSkin') }}>ReSkin</h4>
              <p>
                <strong>Type:</strong> Magnetic skin sensor array<br />
                <strong>Method:</strong> Measures magnetic field distortions from deformation<br />
                <strong>Dimensionality:</strong> 15 features (5 magnetometers × 3D)<br />
                <strong>Strengths:</strong> Low cost, flexible, easy to fabricate
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default SensorComparison;
